import{_ as t,c as e,a2 as a,o as _}from"./chunks/framework.CqbvlPrP.js";const m=JSON.parse('{"title":"第二百一十二章 不要轻视矮小丑陋的人","description":"","frontmatter":{},"headers":[],"relativePath":"meditation/巴利文大藏经/212第二百一十二章 不要轻视矮小丑陋的人.md","filePath":"meditation/巴利文大藏经/212第二百一十二章 不要轻视矮小丑陋的人.md"}'),o={name:"meditation/巴利文大藏经/212第二百一十二章 不要轻视矮小丑陋的人.md"};function r(n,p,i,s,d,c){return _(),e("div",null,p[0]||(p[0]=[a('<h1 id="第二百一十二章-不要轻视矮小丑陋的人" tabindex="-1">第二百一十二章 不要轻视矮小丑陋的人 <a class="header-anchor" href="#第二百一十二章-不要轻视矮小丑陋的人" aria-label="Permalink to &quot;第二百一十二章 不要轻视矮小丑陋的人&quot;">​</a></h1><p>完全读懂巴利文大藏经</p><p>相应部21相应6经/侏儒拔提亚经(比丘相应/因缘篇/如来记说)</p><p>有个时候，佛陀住在舍卫城的祇树林给孤独园，有一天，有一位身材矮小、相貌丑陋的拔提亚尊者来到佛陀的住处，佛陀的一些出家弟子看见这个身材矮小、相貌丑陋的拔提亚尊者就忍不住嘲笑、挖苦他。他们中一些人打趣的对拔提亚尊者说：“小孩子，别到这里来玩，这里是大人们修行的地方，小孩子应该到母亲怀里去吃奶。”</p><p>一些出家人故意阴阳怪气的反驳到：“他吃什么奶哦，你们不知道他的母亲都被他吓的不敢见人了吗！真是丑出了境界。”</p><p>这时，佛陀从屋里走出来，听见这些出家人的言语后，就对他们说：“弟子们，你们不要轻视、瞧不起拔提亚尊者，他是已经证悟解脱果位的圣者，他已经灭除了一切的烦恼和痛苦，他已经证悟达到了涅槃的境界，你们出家修行是为了灭除一切的烦恼和痛苦，从生死轮回中永远的解脱出来，最终达到不生不灭涅槃的境界。你们出家这么久了还是无法证悟解脱的果位。可是拔提亚尊者他已经证悟了解脱的果位，你们不感到惭愧吗？你们如此的诋毁他，只会让你们自己陷入无尽的烦恼和痛苦之中。</p><p>天鹅、白鹭、孔雀、梅花鹿、大象，它们长的漂亮，长的高大，可是它们却畏惧害怕森林之王狮子！不要因为身材的高低，长相的美丑就轻视、瞧不起任何人。一个人他能力、本事的大小不在于他身材的高低、长相的美丑。同样的道理，弟子们，就算是身材矮小、长相丑陋的出家人、修行人，他们也可能是已经开启智慧，已经证悟解脱果位的大圣者。如果没有开启智慧，没有证悟解脱果位，光是身材高大、长相漂亮又有什么用呢？不过是一个身材高大、相貌漂亮的愚痴之人而已。世间的人会赞叹那些已经开启智慧，已经除灭一切烦恼和痛苦，已经证悟解脱果位的人，会赞叹那些已经达到涅槃境界的人，就算他们身材矮小、长相丑陋世间人也会称赞他们。世间人不会称赞那些没有开启智慧，没有除灭烦恼和痛苦，没有证悟解脱果位的人，不会称赞那些没有达到涅槃境界的人，就算他们身体高大、长相漂亮世间人也不会称赞他们，世间人会认为他们是愚昧无知的人。”</p><p>这时，佛陀说偈言：</p><p>「鹅白鹭孔雀，</p><p>大象与斑鹿，</p><p>悉皆畏狮子，</p><p>身无相等者。</p><p>如是于人中，</p><p>矮丑证解脱，</p><p>赞叹彼为圣，</p><p>非赞大愚身。」</p><p>佛陀说法后，这些嘲笑、挖苦拔提亚尊者的出家人们都惭愧的低下了头，在场听法的出家弟子们都虔诚的顶礼佛陀，随喜赞叹佛陀说法的无量功德，他们都按着佛陀所说的法去修行。</p>',17)]))}const f=t(o,[["render",r]]);export{m as __pageData,f as default};
